  VALUES
  ($q$Definition and Scope of Economics$q$, $q$A student has ₦3,000 and must choose between a textbook and a football. If she buys the textbook, what is her opportunity cost?$q$, $q${"A":"The football she gives up","B":"The price of both items","C":"The money she still owns","D":"The value of every book in the shop"}$q$::jsonb, $q$A$q$, $q$Opportunity cost is the value of the next best alternative forgone.$q$),
  ($q$Definition and Scope of Economics$q$, $q$A workshop can produce either 40 stools or 20 desks with its current resources. What does a point beyond its production possibility curve represent?$q$, $q${"A":"Inefficient use of resources","B":"Output unattainable with current resources","C":"A feasible mix of stools and desks","D":"A point with no opportunity cost"}$q$::jsonb, $q$B$q$, $q$Points outside the curve require more or better resources than are currently available.$q$),
  ($q$Definition and Scope of Economics$q$, $q$A farmer grows maize, a mill turns it into flour, and a trader sells the flour. Which activity is secondary production?$q$, $q${"A":"Growing the maize","B":"Selling the flour","C":"Milling maize into flour","D":"Eating the flour"}$q$::jsonb, $q$C$q$, $q$Secondary production transforms raw materials into manufactured goods.$q$),
  ($q$Definition and Scope of Economics$q$, $q$A family ranks food above a new television when planning its spending. This ranking is a what?$q$, $q${"A":"Production schedule","B":"Balance of payments","C":"Price index","D":"Scale of preference"}$q$::jsonb, $q$D$q$, $q$A scale of preference orders wants according to their importance.$q$),
  ($q$Definition and Scope of Economics$q$, $q$A town has idle machines and unemployed workers. On a production possibility diagram, its output lies where?$q$, $q${"A":"Inside the curve","B":"Outside the curve","C":"Only at the vertical intercept","D":"At every point on the curve"}$q$::jsonb, $q$A$q$, $q$Unused resources imply production below the feasible frontier.$q$),
  ($q$Definition and Scope of Economics$q$, $q$If making one extra chair means making two fewer tables, what is the opportunity cost of that chair?$q$, $q${"A":"One table","B":"Two tables","C":"Three tables","D":"The chair itself"}$q$::jsonb, $q$B$q$, $q$The forgone two tables are the next best output sacrificed.$q$),
  ($q$Definition and Scope of Economics$q$, $q$A shopkeeper decides how much stock to buy after observing customers' needs. Which basic economic problem is being addressed?$q$, $q${"A":"How to calculate national income","B":"How to set a foreign exchange rate","C":"What to produce and in what quantity","D":"How to count the population"}$q$::jsonb, $q$C$q$, $q$Choosing stock addresses which goods and quantities should be supplied.$q$),
  ($q$Definition and Scope of Economics$q$, $q$An economy shifts workers from mining to software services. Which classification best describes the change?$q$, $q${"A":"From tertiary to primary activity","B":"From secondary to primary activity","C":"From consumption to saving","D":"From primary to tertiary activity"}$q$::jsonb, $q$D$q$, $q$Mining extracts raw materials; software services belong to the tertiary sector.$q$),
  ($q$Factors of Production$q$, $q$A baker rents a shop, hires assistants, buys an oven and plans the business. Which factor does the oven represent?$q$, $q${"A":"Capital","B":"Land","C":"Labour","D":"Entrepreneurship"}$q$::jsonb, $q$A$q$, $q$Capital is a produced asset used to make other goods and services.$q$),
  ($q$Factors of Production$q$, $q$The same baker combines resources and bears the risk of a new product line. Which factor is she providing?$q$, $q${"A":"Land","B":"Entrepreneurship","C":"Unskilled labour","D":"Natural resources"}$q$::jsonb, $q$B$q$, $q$Entrepreneurship organizes the other factors and accepts business risk.$q$),
  ($q$Factors of Production$q$, $q$A fish pond is used to raise tilapia. In economics, the pond's water and site are mainly classified as what?$q$, $q${"A":"Capital","B":"Labour","C":"Land","D":"Profit"}$q$::jsonb, $q$C$q$, $q$Land includes natural resources used in production.$q$),
  ($q$Factors of Production$q$, $q$Training workers to repair solar panels raises their productivity. What is being improved?$q$, $q${"A":"The quantity of land","B":"The money supply","C":"The market price","D":"Human capital"}$q$::jsonb, $q$D$q$, $q$Education and skills increase human capital.$q$),
  ($q$Factors of Production$q$, $q$A factory replaces hand-operated equipment with a machine to increase output per worker. Which factor has increased?$q$, $q${"A":"Capital","B":"Land","C":"Entrepreneurship only","D":"Consumption"}$q$::jsonb, $q$A$q$, $q$The machine is capital used alongside labour.$q$),
  ($q$Factors of Production$q$, $q$A trained nurse moves to another hospital to fill a vacancy. This is an example of what?$q$, $q${"A":"Capital depreciation","B":"Occupational or geographical labour mobility","C":"Land reclamation","D":"Price discrimination"}$q$::jsonb, $q$B$q$, $q$Labour mobility is the ability of workers to change jobs or locations.$q$),
  ($q$Factors of Production$q$, $q$Why might a firm pay a specialist technician more than an untrained worker?$q$, $q${"A":"All technicians work longer hours by law","B":"Training removes the need for capital","C":"The technician's scarce skills can raise productivity","D":"The technician owns the factory land"}$q$::jsonb, $q$C$q$, $q$Scarce relevant skills can increase a worker's contribution to output and wage.$q$),
  ($q$Factors of Production$q$, $q$An entrepreneur's income for successful risk-taking is usually called what?$q$, $q${"A":"Rent","B":"Wages","C":"Interest","D":"Profit"}$q$::jsonb, $q$D$q$, $q$Profit is the residual return associated with organizing production and bearing risk.$q$),
  ($q$Types and Basic Features of Economic Systems$q$, $q$In an economy, most factories are privately owned and prices guide production. Which system is most closely described?$q$, $q${"A":"Capitalism","B":"Central planning","C":"Subsistence farming","D":"A barter economy"}$q$::jsonb, $q$A$q$, $q$Private ownership and price signals are key features of capitalism.$q$),
  ($q$Types and Basic Features of Economic Systems$q$, $q$A government owns major industries while private shops operate freely. What type of system is this?$q$, $q${"A":"Pure command economy","B":"Mixed economy","C":"Pure market economy","D":"Barter economy"}$q$::jsonb, $q$B$q$, $q$A mixed economy combines public and private ownership.$q$),
  ($q$Types and Basic Features of Economic Systems$q$, $q$A planning authority fixes output targets for all major factories. Which system relies most on this method?$q$, $q${"A":"Pure capitalism","B":"An informal exchange economy","C":"Socialism or command economy","D":"A household economy"}$q$::jsonb, $q$C$q$, $q$Central planning assigns production targets in a command system.$q$),
  ($q$Types and Basic Features of Economic Systems$q$, $q$A market system rewards firms that satisfy buyers, but it may undersupply street lighting. Why?$q$, $q${"A":"Streetlights use no resources","B":"Every streetlight has a private owner","C":"Demand for light is always zero","D":"Street lighting is hard to exclude non-payers from"}$q$::jsonb, $q$D$q$, $q$Non-excludability creates a free-rider problem and weakens private provision.$q$),
  ($q$Types and Basic Features of Economic Systems$q$, $q$A command economy can direct resources quickly to a national project, but what information problem may it face?$q$, $q${"A":"Planners may not know local preferences and costs","B":"Prices always reveal every preference perfectly","C":"Workers never need equipment","D":"Scarcity disappears"}$q$::jsonb, $q$A$q$, $q$Central planners may lack the detailed information dispersed among consumers and firms.$q$),
  ($q$Types and Basic Features of Economic Systems$q$, $q$Which decision is typically made through market prices in a largely capitalist economy?$q$, $q${"A":"How much rain will fall","B":"Which goods firms find profitable to produce","C":"Who has legal citizenship","D":"The country's geographic boundaries"}$q$::jsonb, $q$B$q$, $q$Profit and price signals guide firms' production decisions.$q$),
  ($q$Types and Basic Features of Economic Systems$q$, $q$A state subsidizes schooling while private firms sell textbooks. What does this combination show?$q$, $q${"A":"Complete abolition of private enterprise","B":"A purely subsistence economy","C":"Public intervention within a mixed economy","D":"The absence of scarcity"}$q$::jsonb, $q$C$q$, $q$Public provision and private sales coexist in a mixed economy.$q$),
  ($q$Types and Basic Features of Economic Systems$q$, $q$Why can no economic system avoid choosing among alternative uses of resources?$q$, $q${"A":"Every government owns factories","B":"All prices are fixed","C":"All households have identical incomes","D":"Resources are scarce relative to wants"}$q$::jsonb, $q$D$q$, $q$Scarcity requires choices regardless of ownership system.$q$),
  ($q$Basic Tools of Economic Analysis$q$, $q$Five households earn ₦20, ₦30, ₦40, ₦50 and ₦60 thousand monthly. What is the mean income?$q$, $q${"A":"₦40,000","B":"₦30,000","C":"₦45,000","D":"₦50,000"}$q$::jsonb, $q$A$q$, $q$Add the five incomes and divide by five: (20 + 30 + 40 + 50 + 60) ÷ 5 = 40 thousand naira.$q$),
  ($q$Basic Tools of Economic Analysis$q$, $q$The prices of a good are ₦4, ₦6, ₦8, ₦10 and ₦12. What is the median price?$q$, $q${"A":"₦6","B":"₦8","C":"₦9","D":"₦10"}$q$::jsonb, $q$B$q$, $q$The five prices are ordered; the middle, third price is ₦8.$q$),
  ($q$Basic Tools of Economic Analysis$q$, $q$A shop sold 2, 3, 3, 5 and 7 bags on five days. What is the mode?$q$, $q${"A":"2 bags","B":"4 bags","C":"3 bags","D":"7 bags"}$q$::jsonb, $q$C$q$, $q$The mode is the value occurring most often; 3 occurs twice.$q$),
  ($q$Basic Tools of Economic Analysis$q$, $q$A bar chart compares harvests in three villages. What should its vertical axis show if villages are on the horizontal axis?$q$, $q${"A":"The names of villages","B":"The title of the chart","C":"The source of the data only","D":"The quantity harvested"}$q$::jsonb, $q$D$q$, $q$The vertical axis carries the measured quantity, while the horizontal axis identifies categories.$q$),
  ($q$Basic Tools of Economic Analysis$q$, $q$A survey recorded 12, 18, 20 and 30 responses in four groups. How many responses were recorded in all?$q$, $q${"A":"80","B":"70","C":"75","D":"90"}$q$::jsonb, $q$A$q$, $q$Add all group frequencies: 12 + 18 + 20 + 30 = 80.$q$),
  ($q$Basic Tools of Economic Analysis$q$, $q$A line graph shows a steady rise in sales over six months. What can be inferred directly?$q$, $q${"A":"The firm's profit certainly increased","B":"Sales increased over the period","C":"Production costs fell","D":"All customers were satisfied"}$q$::jsonb, $q$B$q$, $q$The graph shows sales trend only; it does not prove profit or costs.$q$),
  ($q$Basic Tools of Economic Analysis$q$, $q$Seven prices are ₦2, ₦3, ₦3, ₦5, ₦6, ₦8 and ₦9. What is their median?$q$, $q${"A":"₦3","B":"₦6","C":"₦5","D":"₦8"}$q$::jsonb, $q$C$q$, $q$With seven ordered values, the fourth value is the median: ₦5.$q$),
  ($q$Basic Tools of Economic Analysis$q$, $q$Which display best shows how four spending categories make up one household budget?$q$, $q${"A":"A scatter diagram","B":"A single price label","C":"A time-series line alone","D":"A pie chart"}$q$::jsonb, $q$D$q$, $q$A pie chart shows each category's share of a whole.$q$),
  ($q$Demand$q$, $q$A clothing shop lowers the price of shirts and sells more, with other factors unchanged. This is a what?$q$, $q${"A":"Movement along the demand curve","B":"Rightward shift of the demand curve","C":"Leftward shift of supply","D":"Fall in consumer income"}$q$::jsonb, $q$A$q$, $q$A change in a good's own price changes quantity demanded along its curve.$q$),
  ($q$Demand$q$, $q$Tea and coffee are substitutes. If coffee becomes more expensive, what is likely to happen to demand for tea?$q$, $q${"A":"It decreases","B":"It increases","C":"It must become zero","D":"It becomes perfectly inelastic"}$q$::jsonb, $q$B$q$, $q$Consumers may switch from dearer coffee to tea, shifting tea demand right.$q$),
  ($q$Demand$q$, $q$A family earns more and buys fewer low-quality staple substitutes. Such staples are what type of goods for this family?$q$, $q${"A":"Normal goods","B":"Public goods","C":"Inferior goods","D":"Capital goods"}$q$::jsonb, $q$C$q$, $q$Demand for an inferior good can fall as income rises.$q$),
  ($q$Demand$q$, $q$The price of a product rises from ₦10 to ₦12 and quantity demanded falls from 100 to 90 units. Using the original values, what is price elasticity of demand?$q$, $q${"A":"1.0","B":"2.0","C":"5.0","D":"0.5"}$q$::jsonb, $q$D$q$, $q$Percentage quantity change = 10/100 = 10%; percentage price change = 2/10 = 20%; elasticity magnitude = 10% ÷ 20% = 0.5.$q$),
  ($q$Demand$q$, $q$A bus company raises fares and total fare revenue falls. What does this suggest about demand over that range?$q$, $q${"A":"It is price elastic","B":"It is perfectly inelastic","C":"It has zero elasticity","D":"It is necessarily unit elastic"}$q$::jsonb, $q$A$q$, $q$When a price rise lowers total revenue, the proportionate fall in quantity exceeds the price rise.$q$),
  ($q$Demand$q$, $q$Demand for bread rises because more households move into a town. What changes on the demand diagram?$q$, $q${"A":"There is a movement up one demand curve","B":"The demand curve shifts right","C":"The supply curve must become vertical","D":"The demand curve shifts left"}$q$::jsonb, $q$B$q$, $q$More buyers increase demand at each price, shifting the demand curve right.$q$),
  ($q$Demand$q$, $q$Income rises by 10% and demand for a product rises by 15%. What is income elasticity of demand?$q$, $q${"A":"0.5","B":"1.0","C":"1.5","D":"2.5"}$q$::jsonb, $q$C$q$, $q$Income elasticity = percentage change in quantity demanded ÷ percentage change in income = 15% ÷ 10% = 1.5.$q$),
  ($q$Demand$q$, $q$The price of maize rises by 20%, and demand for millet rises by 10%. What is the cross elasticity of demand for millet with respect to maize price?$q$, $q${"A":"−0.5","B":"+2.0","C":"−2.0","D":"+0.5"}$q$::jsonb, $q$D$q$, $q$Cross elasticity = percentage change in millet demand ÷ percentage change in maize price = 10% ÷ 20% = +0.5.$q$),
  ($q$Supply$q$, $q$A bakery raises the price of its bread and offers more loaves for sale, other things unchanged. This is a what?$q$, $q${"A":"Movement along the supply curve","B":"Rightward shift of demand","C":"Leftward shift of supply","D":"Fall in input costs"}$q$::jsonb, $q$A$q$, $q$A change in the good's own price changes quantity supplied along the curve.$q$),
  ($q$Supply$q$, $q$A new oven lets a bakery produce each loaf at lower cost. What happens to its supply curve?$q$, $q${"A":"It shifts left","B":"It shifts right","C":"It becomes a demand curve","D":"It stays fixed at every price"}$q$::jsonb, $q$B$q$, $q$Lower production costs increase the quantity firms offer at each price.$q$),
  ($q$Supply$q$, $q$Price rises from ₦20 to ₦25 and quantity supplied rises from 80 to 100 units. Using original values, what is price elasticity of supply?$q$, $q${"A":"0.5","B":"1.5","C":"1.0","D":"2.0"}$q$::jsonb, $q$C$q$, $q$Quantity rises 20/80 = 25%; price rises 5/20 = 25%; elasticity of supply = 25% ÷ 25% = 1.0.$q$),
  ($q$Supply$q$, $q$A farm can switch land quickly between maize and beans. Compared with a farm with fixed equipment, its supply is likely to be what?$q$, $q${"A":"Less price elastic","B":"Perfectly inelastic","C":"Unrelated to price","D":"More price elastic"}$q$::jsonb, $q$D$q$, $q$Ease of switching resources allows a stronger output response to price changes.$q$),
  ($q$Supply$q$, $q$A drought reduces cocoa output at every possible price. What happens to cocoa supply?$q$, $q${"A":"The supply curve shifts left","B":"There is movement down one supply curve","C":"The demand curve shifts right automatically","D":"Price elasticity becomes infinite"}$q$::jsonb, $q$A$q$, $q$Drought reduces the quantity producers can supply at each price.$q$),
  ($q$Supply$q$, $q$A farmer can use the same field to grow maize or beans next season. How are the supplies of these crops related?$q$, $q${"A":"Joint supply","B":"Competitive supply","C":"Composite demand","D":"Derived demand"}$q$::jsonb, $q$B$q$, $q$Competitive supply occurs when the same resource, such as land, can produce either of two alternative crops.$q$),
  ($q$Supply$q$, $q$Meat and hides emerge from processing cattle. Their supply relationship is what?$q$, $q${"A":"Competitive supply","B":"Derived demand","C":"Joint supply","D":"Composite demand"}$q$::jsonb, $q$C$q$, $q$Joint supply arises when one production process yields two products.$q$),
  ($q$Supply$q$, $q$Quantity supplied rises from 50 to 55 units when price rises from ₦10 to ₦12. Using original values, what is supply elasticity?$q$, $q${"A":"1.0","B":"2.0","C":"5.0","D":"0.5"}$q$::jsonb, $q$D$q$, $q$Quantity rises 5/50 = 10%; price rises 2/10 = 20%; elasticity = 10% ÷ 20% = 0.5.$q$),
  ($q$Theory of Consumer Behaviour$q$, $q$Total utility rises from 30 to 36 units when a consumer buys a fourth orange. What is marginal utility of the fourth orange?$q$, $q${"A":"6 units","B":"9 units","C":"30 units","D":"36 units"}$q$::jsonb, $q$A$q$, $q$Marginal utility is the change in total utility from one extra unit: 36 − 30 = 6.$q$),
  ($q$Theory of Consumer Behaviour$q$, $q$A consumer gets 24 utility units from three identical cups of tea. What is average utility per cup?$q$, $q${"A":"3 units","B":"8 units","C":"21 units","D":"72 units"}$q$::jsonb, $q$B$q$, $q$Average utility = total utility ÷ quantity = 24 ÷ 3 = 8.$q$),
  ($q$Theory of Consumer Behaviour$q$, $q$A consumer's satisfaction from each extra biscuit falls as more biscuits are eaten. What principle is shown?$q$, $q${"A":"Increasing total cost","B":"Perfectly elastic demand","C":"Diminishing marginal utility","D":"Economies of scale"}$q$::jsonb, $q$C$q$, $q$Diminishing marginal utility means each additional unit adds less satisfaction.$q$),
  ($q$Theory of Consumer Behaviour$q$, $q$A student has ₦20 to spend and chooses between snacks and notebooks. What limits the combinations she can buy?$q$, $q${"A":"The producer's profit only","B":"The national income total","C":"The exchange rate alone","D":"Her budget constraint"}$q$::jsonb, $q$D$q$, $q$A budget constraint lists affordable combinations at given prices and income.$q$),
  ($q$Theory of Consumer Behaviour$q$, $q$A fourth unit adds 5 utility units, while the fifth adds 2. By how many units does marginal utility fall?$q$, $q${"A":"3","B":"2","C":"5","D":"7"}$q$::jsonb, $q$A$q$, $q$Marginal utility falls from 5 to 2, a decrease of 5 − 2 = 3 units.$q$),
  ($q$Theory of Consumer Behaviour$q$, $q$Why might a consumer buy more of a good after its price falls, assuming income is unchanged?$q$, $q${"A":"Its total utility must become negative","B":"Its marginal utility per naira becomes more attractive","C":"Its supply must fall to zero","D":"Its production cost must rise"}$q$::jsonb, $q$B$q$, $q$A lower price can increase utility gained per unit of spending.$q$),
  ($q$Theory of Consumer Behaviour$q$, $q$Good A gives 12 utility units per ₦4 spent and good B gives 10 per ₦5. Which gives more marginal utility per naira?$q$, $q${"A":"Good B","B":"Both are equal","C":"Good A","D":"Neither can be compared"}$q$::jsonb, $q$C$q$, $q$A gives 12 ÷ 4 = 3 utility units per naira; B gives 10 ÷ 5 = 2, so A gives more.$q$),
  ($q$Theory of Consumer Behaviour$q$, $q$At a consumer optimum across two goods, what is equalized, assuming divisible goods and no other constraints?$q$, $q${"A":"Their total quantities","B":"Their market prices","C":"Their total utilities","D":"Marginal utility per unit of money spent"}$q$::jsonb, $q$D$q$, $q$The last naira spent on each good should yield equal marginal utility.$q$),
  ($q$Theory of Price Determination$q$, $q$At ₦5, buyers demand 60 units and sellers supply 40. What shortage exists?$q$, $q${"A":"20 units","B":"10 units","C":"40 units","D":"100 units"}$q$::jsonb, $q$A$q$, $q$Shortage = quantity demanded − quantity supplied = 60 − 40 = 20.$q$),
  ($q$Theory of Price Determination$q$, $q$At ₦8, sellers supply 90 units and buyers demand 70. What surplus exists?$q$, $q${"A":"10 units","B":"20 units","C":"70 units","D":"160 units"}$q$::jsonb, $q$B$q$, $q$Surplus = quantity supplied − quantity demanded = 90 − 70 = 20.$q$),
  ($q$Theory of Price Determination$q$, $q$If demand rises while supply is unchanged, what usually happens to equilibrium price and quantity?$q$, $q${"A":"Both fall","B":"Price falls and quantity rises","C":"Both rise","D":"Price rises and quantity falls"}$q$::jsonb, $q$C$q$, $q$A rightward demand shift moves equilibrium to a higher price and quantity.$q$),
  ($q$Theory of Price Determination$q$, $q$A government sets a maximum price below the market equilibrium price. What is a likely immediate result?$q$, $q${"A":"A surplus","B":"No change in quantity demanded","C":"A guaranteed increase in supply","D":"A shortage"}$q$::jsonb, $q$D$q$, $q$The lower controlled price raises quantity demanded while reducing quantity supplied.$q$),
  ($q$Theory of Price Determination$q$, $q$A guaranteed minimum price is fixed above equilibrium. What is likely to appear?$q$, $q${"A":"A surplus","B":"A shortage","C":"A lower supply quantity","D":"A fall in demand at every price"}$q$::jsonb, $q$A$q$, $q$At the higher price, suppliers offer more than buyers demand.$q$),
  ($q$Theory of Price Determination$q$, $q$Demand is Qd = 100 − 2P and supply is Qs = 20 + 2P. What is the equilibrium price?$q$, $q${"A":"₦10","B":"₦20","C":"₦25","D":"₦40"}$q$::jsonb, $q$B$q$, $q$Set demand equal to supply: 100 − 2P = 20 + 2P; 80 = 4P; P = 20.$q$),
  ($q$Theory of Price Determination$q$, $q$Using Qd = 100 − 2P and Qs = 20 + 2P, what is equilibrium quantity?$q$, $q${"A":"40 units","B":"80 units","C":"60 units","D":"100 units"}$q$::jsonb, $q$C$q$, $q$Equilibrium price is ₦20. Substitute into demand: Q = 100 − 2(20) = 60.$q$),
  ($q$Theory of Price Determination$q$, $q$A legal price ceiling leads some sellers to trade secretly at higher prices. What is the unofficial trade called?$q$, $q${"A":"A futures market","B":"A capital market","C":"A labour exchange","D":"A black market"}$q$::jsonb, $q$D$q$, $q$A black market trades outside price regulations, often at prices above the ceiling.$q$),
  ($q$Theory of Production$q$, $q$In a workshop, one worker repeatedly cuts fabric while another stitches it. This is what?$q$, $q${"A":"Division of labour","B":"Price discrimination","C":"Capital depreciation","D":"Consumer equilibrium"}$q$::jsonb, $q$A$q$, $q$Division of labour splits production into specialized tasks.$q$),
  ($q$Theory of Production$q$, $q$A farm produces 240 bags with 8 workers. What is average product per worker?$q$, $q${"A":"8 bags","B":"30 bags","C":"32 bags","D":"248 bags"}$q$::jsonb, $q$B$q$, $q$Average product = total product ÷ workers = 240 ÷ 8 = 30 bags.$q$),
  ($q$Theory of Production$q$, $q$With four workers, output is 90 units; with five it is 108. What is the fifth worker's marginal product?$q$, $q${"A":"22 units","B":"90 units","C":"18 units","D":"108 units"}$q$::jsonb, $q$C$q$, $q$Marginal product = change in total output = 108 − 90 = 18 units.$q$),
  ($q$Theory of Production$q$, $q$A large firm buys raw materials in bulk and gets a lower unit price. What does it enjoy?$q$, $q${"A":"External diseconomies","B":"Diminishing demand","C":"A fall in total output","D":"Internal economies of scale"}$q$::jsonb, $q$D$q$, $q$Bulk purchasing can lower the firm's average cost as its scale grows.$q$),
  ($q$Theory of Production$q$, $q$A new road serving every factory in an industrial area lowers transport costs. This is what?$q$, $q${"A":"An external economy","B":"An internal diseconomy","C":"Price discrimination","D":"A fixed cost"}$q$::jsonb, $q$A$q$, $q$A benefit shared by multiple firms from the surrounding industry is external.$q$),
  ($q$Theory of Production$q$, $q$When more workers use the same fixed land, each additional worker eventually adds less output. What law is illustrated?$q$, $q${"A":"Increasing returns forever","B":"Diminishing returns to a variable factor","C":"The law of demand","D":"Perfect competition"}$q$::jsonb, $q$B$q$, $q$With a fixed factor, extra variable input can eventually yield smaller marginal additions.$q$),
  ($q$Theory of Production$q$, $q$Total output rises from 300 to 318 units after one extra worker is hired. What is marginal product?$q$, $q${"A":"6 units","B":"300 units","C":"18 units","D":"618 units"}$q$::jsonb, $q$C$q$, $q$Marginal product is the output increase caused by one additional worker: 318 − 300 = 18.$q$),
  ($q$Theory of Production$q$, $q$A bakery specializing workers gains speed but finds workers bored by repetitive tasks. What is the boredom an example of?$q$, $q${"A":"An increase in land supply","B":"A benefit of monopoly","C":"A decrease in fixed cost","D":"A disadvantage of specialization"}$q$::jsonb, $q$D$q$, $q$Repetitive specialized work can reduce motivation or flexibility.$q$),
  ($q$Theory of Cost and Revenue$q$, $q$A firm's fixed cost is ₦200 and variable cost is ₦300 at an output of 10 units. What is total cost?$q$, $q${"A":"₦500","B":"₦100","C":"₦300","D":"₦2,000"}$q$::jsonb, $q$A$q$, $q$Total cost = fixed cost + variable cost = 200 + 300 = ₦500.$q$),
  ($q$Theory of Cost and Revenue$q$, $q$If total cost is ₦500 for 10 units, what is average cost?$q$, $q${"A":"₦5","B":"₦50","C":"₦500","D":"₦5,000"}$q$::jsonb, $q$B$q$, $q$Average cost = total cost ÷ output = 500 ÷ 10 = ₦50.$q$),
  ($q$Theory of Cost and Revenue$q$, $q$Total cost rises from ₦500 to ₦560 when output rises from 10 to 11 units. What is marginal cost?$q$, $q${"A":"₦56","B":"₦500","C":"₦60","D":"₦1,060"}$q$::jsonb, $q$C$q$, $q$Marginal cost for the extra unit = 560 − 500 = ₦60.$q$),
  ($q$Theory of Cost and Revenue$q$, $q$A firm sells 20 units at ₦15 each. What is total revenue?$q$, $q${"A":"₦35","B":"₦150","C":"₦1.33","D":"₦300"}$q$::jsonb, $q$D$q$, $q$Total revenue = price × quantity = 15 × 20 = ₦300.$q$),
  ($q$Theory of Cost and Revenue$q$, $q$Total revenue rises from ₦300 to ₦318 when sales rise from 20 to 21 units. What is marginal revenue?$q$, $q${"A":"₦18","B":"₦15","C":"₦21","D":"₦318"}$q$::jsonb, $q$A$q$, $q$Marginal revenue is the additional revenue from the extra unit: 318 − 300 = ₦18.$q$),
  ($q$Theory of Cost and Revenue$q$, $q$A small shop uses its owner's building without paying rent. What cost would an economist include that an accountant may omit?$q$, $q${"A":"The electricity bill actually paid","B":"The forgone rent from leasing the building","C":"The wage paid to staff","D":"The price of purchased goods"}$q$::jsonb, $q$B$q$, $q$An economist counts implicit opportunity costs, including rent forgone by using one's own building.$q$),
  ($q$Theory of Cost and Revenue$q$, $q$A firm earns ₦900 revenue and pays ₦700 explicit costs, while the owner's forgone wage is ₦120. What is economic profit?$q$, $q${"A":"₦200","B":"₦120","C":"₦80","D":"₦1,600"}$q$::jsonb, $q$C$q$, $q$Economic profit = revenue − explicit costs − implicit cost = 900 − 700 − 120 = ₦80.$q$),
  ($q$Theory of Cost and Revenue$q$, $q$A firm earns ₦600 total revenue from selling 12 units. What is average revenue?$q$, $q${"A":"₦12","B":"₦600","C":"₦7,200","D":"₦50"}$q$::jsonb, $q$D$q$, $q$Average revenue = total revenue ÷ quantity = 600 ÷ 12 = ₦50.$q$),
  ($q$Market Structures$q$, $q$Many sellers offer identical bags of grain, and none can change the market price alone. Which market is closest to this description?$q$, $q${"A":"Perfect competition","B":"Monopoly","C":"Monopolistic competition","D":"A bilateral monopoly"}$q$::jsonb, $q$A$q$, $q$Many sellers and homogeneous goods make each firm a price taker.$q$),
  ($q$Market Structures$q$, $q$One licensed firm is the only supplier of water in a town. Which market structure is illustrated?$q$, $q${"A":"Perfect competition","B":"Monopoly","C":"Monopolistic competition","D":"A farmers' co-operative"}$q$::jsonb, $q$B$q$, $q$A monopoly has one seller with no close substitute in the defined market.$q$),
  ($q$Market Structures$q$, $q$Several cafés sell similar but differentiated meals and can set slightly different prices. Which structure fits best?$q$, $q${"A":"Perfect competition","B":"Pure monopoly","C":"Monopolistic competition","D":"A market with no buyers"}$q$::jsonb, $q$C$q$, $q$Many sellers with differentiated products characterize monopolistic competition.$q$),
  ($q$Market Structures$q$, $q$A cinema charges students less than adults for the same seat at the same showing. What pricing practice is this?$q$, $q${"A":"Cost-plus pricing","B":"A uniform market price","C":"Barter","D":"Price discrimination"}$q$::jsonb, $q$D$q$, $q$Charging different customer groups different prices for the same service is price discrimination.$q$),
  ($q$Market Structures$q$, $q$A price-taking farmer sells one extra basket at the market price. How does marginal revenue compare with price?$q$, $q${"A":"It equals price","B":"It is always zero","C":"It is twice price","D":"It is negative"}$q$::jsonb, $q$A$q$, $q$A price taker receives the same price for each extra unit sold, so MR = price.$q$),
  ($q$Market Structures$q$, $q$Why can a monopolist often restrict output to raise its selling price?$q$, $q${"A":"It faces a perfectly horizontal demand curve","B":"It controls the market supply of a product with few close substitutes","C":"It has no production costs","D":"It cannot choose its output"}$q$::jsonb, $q$B$q$, $q$Market power lets a monopolist influence price by altering output.$q$),
  ($q$Market Structures$q$, $q$A seller advertises a unique brand to make its product seem different from rivals'. Which market behaviour is this?$q$, $q${"A":"Perfectly homogeneous output","B":"A legal price ceiling","C":"Product differentiation","D":"A producer subsidy"}$q$::jsonb, $q$C$q$, $q$Product differentiation makes buyers perceive one seller's offer as distinct.$q$),
  ($q$Market Structures$q$, $q$In a competitive market, a firm keeps producing an extra unit while its marginal revenue exceeds marginal cost. Why?$q$, $q${"A":"Fixed cost becomes zero","B":"The market price must fall to zero","C":"Average revenue becomes negative","D":"The extra unit adds more revenue than cost"}$q$::jsonb, $q$D$q$, $q$An extra unit raises profit when its added revenue exceeds its added cost.$q$),
  ($q$Business Organizations$q$, $q$A trader owns and controls a shop alone and bears its debts personally. What form of enterprise is this?$q$, $q${"A":"Sole proprietorship","B":"Public limited company","C":"Statutory corporation","D":"Co-operative society"}$q$::jsonb, $q$A$q$, $q$A sole proprietor owns the business alone and generally has unlimited liability.$q$),
  ($q$Business Organizations$q$, $q$Two friends share ownership and profits under a written agreement. Which form is most likely?$q$, $q${"A":"Sole proprietorship","B":"Partnership","C":"A state corporation","D":"A workers' union"}$q$::jsonb, $q$B$q$, $q$A partnership is a business carried on by two or more owners.$q$),
  ($q$Business Organizations$q$, $q$Farmers pool resources to buy inputs and share benefits as members. What organization have they formed?$q$, $q${"A":"A monopoly regulator","B":"A stock exchange","C":"A co-operative","D":"A central bank"}$q$::jsonb, $q$C$q$, $q$A co-operative is owned and run for the benefit of its members.$q$),
  ($q$Business Organizations$q$, $q$A company is sold by the state to private investors. What policy does this illustrate?$q$, $q${"A":"Nationalization","B":"Rationing","C":"A tariff","D":"Privatization"}$q$::jsonb, $q$D$q$, $q$Privatization transfers ownership from the public to the private sector.$q$),
  ($q$Business Organizations$q$, $q$A state enterprise stays publicly owned but is expected to cover costs from sales. What policy is this?$q$, $q${"A":"Commercialization","B":"Privatization","C":"Barter","D":"A merger"}$q$::jsonb, $q$A$q$, $q$Commercialization makes a public enterprise operate on business principles without necessarily changing ownership.$q$),
  ($q$Business Organizations$q$, $q$A company sells shares to many investors but owners' losses are limited to their investment. Which feature is described?$q$, $q${"A":"Unlimited liability","B":"Limited liability","C":"Price control","D":"Public ownership only"}$q$::jsonb, $q$B$q$, $q$Limited liability caps shareholders' exposure at the value of their investment.$q$),
  ($q$Business Organizations$q$, $q$A joint venture lets two firms share the cost of building a new plant. What is a likely benefit?$q$, $q${"A":"Scarcity disappears","B":"No management is needed","C":"Risk and finance are shared","D":"The law of demand no longer applies"}$q$::jsonb, $q$C$q$, $q$Partners can pool capital, expertise and business risks.$q$),
  ($q$Business Organizations$q$, $q$A government takes private ownership of a railway into state ownership. What is this called?$q$, $q${"A":"Privatization","B":"Commercialization","C":"Franchising","D":"Nationalization"}$q$::jsonb, $q$D$q$, $q$Nationalization transfers a private enterprise into public ownership.$q$),
  ($q$Distributive Trade$q$, $q$A manufacturer sells 500 cartons to one wholesaler rather than to many small shops. What role does the wholesaler perform?$q$, $q${"A":"Bulk buying and breaking bulk","B":"Setting monetary policy","C":"Issuing passports","D":"Mining raw materials"}$q$::jsonb, $q$A$q$, $q$Wholesalers buy large quantities and resell smaller lots to retailers.$q$),
  ($q$Distributive Trade$q$, $q$A neighbourhood shop sells individual packets directly to households. The shop is a what?$q$, $q${"A":"Wholesaler","B":"Retailer","C":"Producer of raw materials","D":"Central bank"}$q$::jsonb, $q$B$q$, $q$Retailers sell goods to final consumers.$q$),
  ($q$Distributive Trade$q$, $q$A rural co-operative collects members' crops and negotiates with buyers. What advantage does this give members?$q$, $q${"A":"Guaranteed zero transport cost","B":"A fixed world price","C":"Stronger collective bargaining","D":"The end of storage needs"}$q$::jsonb, $q$C$q$, $q$Pooling produce can improve bargaining power and market access.$q$),
  ($q$Distributive Trade$q$, $q$Perishable tomatoes spoil before they reach distant towns. Which improvement would most directly reduce this loss?$q$, $q${"A":"More advertising alone","B":"A higher income tax","C":"Fewer market stalls only","D":"Better cold-chain transport"}$q$::jsonb, $q$D$q$, $q$Cooling and faster transport help preserve perishable produce.$q$),
  ($q$Distributive Trade$q$, $q$A producer sells online directly to customers, bypassing a retailer. What change has occurred?$q$, $q${"A":"One intermediary has been removed","B":"The producer has stopped producing","C":"The goods have become public goods","D":"The customers have become wholesalers"}$q$::jsonb, $q$A$q$, $q$Direct sales shorten the distribution chain.$q$),
  ($q$Distributive Trade$q$, $q$A retailer keeps small quantities close to customers' homes. Which service is being provided?$q$, $q${"A":"Foreign exchange management","B":"Convenient access in small units","C":"National income accounting","D":"Mining"}$q$::jsonb, $q$B$q$, $q$Retailers make products available in convenient places and quantities.$q$),
  ($q$Distributive Trade$q$, $q$A produce market lacks reliable price information, and farmers accept low offers. What would help most?$q$, $q${"A":"A longer route to market","B":"Less communication","C":"Timely market-price information","D":"A ban on weighing produce"}$q$::jsonb, $q$C$q$, $q$Knowing prevailing prices helps farmers evaluate buyers' offers.$q$),
  ($q$Distributive Trade$q$, $q$A commodity board buys crops at a guaranteed price. What is one intended effect?$q$, $q${"A":"Elimination of all production risk","B":"A permanent end to imports","C":"A guaranteed world price increase","D":"More stable income for farmers"}$q$::jsonb, $q$D$q$, $q$A guaranteed purchase price can reduce farmers' price uncertainty.$q$),
  ($q$Population and Labour Market$q$, $q$A town has 12,000 residents on 30 square kilometres. What is its population density?$q$, $q${"A":"400 people per km²","B":"40 people per km²","C":"360 people per km²","D":"12,030 people per km²"}$q$::jsonb, $q$A$q$, $q$Population density = population ÷ area = 12,000 ÷ 30 = 400 people per km².$q$),
  ($q$Population and Labour Market$q$, $q$A country has 2 million employed people and 0.5 million unemployed people actively seeking work. What is its labour force?$q$, $q${"A":"1.5 million","B":"2.5 million","C":"2 million","D":"0.5 million"}$q$::jsonb, $q$B$q$, $q$Labour force includes the employed plus unemployed people actively seeking work: 2 + 0.5 = 2.5 million.$q$),
  ($q$Population and Labour Market$q$, $q$There are 200 unemployed job seekers in a labour force of 2,000. What is the unemployment rate?$q$, $q${"A":"20%","B":"5%","C":"10%","D":"90%"}$q$::jsonb, $q$C$q$, $q$Unemployment rate = unemployed ÷ labour force × 100 = 200 ÷ 2,000 × 100 = 10%.$q$),
  ($q$Population and Labour Market$q$, $q$A graduate moves from a village to a city after finding a job there. What demographic movement is this?$q$, $q${"A":"Urban-to-rural migration","B":"Natural increase","C":"International emigration","D":"Rural-to-urban migration"}$q$::jsonb, $q$D$q$, $q$Moving from a rural settlement to a city is rural-to-urban migration.$q$),
  ($q$Population and Labour Market$q$, $q$A trained engineer cannot find engineering work and takes a job that uses very few of her skills. What condition is illustrated?$q$, $q${"A":"Underemployment","B":"Full employment","C":"Structural inflation","D":"Population density"}$q$::jsonb, $q$A$q$, $q$Underemployment includes work that makes insufficient use of a worker's skills or time.$q$),
  ($q$Population and Labour Market$q$, $q$A national census misses people in remote villages. What is the likely statistical effect?$q$, $q${"A":"Population is always overestimated","B":"Population is underestimated","C":"Births are counted twice automatically","D":"The labour force becomes zero"}$q$::jsonb, $q$B$q$, $q$Undercounting residents makes the recorded population too low.$q$),
  ($q$Population and Labour Market$q$, $q$A trade union negotiates collectively for safer conditions. What is the union's role?$q$, $q${"A":"Fixing the exchange rate","B":"Issuing government bonds","C":"Representing workers' interests","D":"Managing all firms"}$q$::jsonb, $q$C$q$, $q$Trade unions bargain on behalf of workers over pay and conditions.$q$),
  ($q$Population and Labour Market$q$, $q$Employers demand more trained welders after new factories open. What is most likely to happen to welders' wages if supply does not immediately rise?$q$, $q${"A":"They must fall to zero","B":"They cannot change","C":"They are set by population density","D":"They tend to rise"}$q$::jsonb, $q$D$q$, $q$Stronger demand for scarce welders tends to raise the wage.$q$),
  ($q$Agriculture$q$, $q$A farm grows crops mainly for the household's consumption with little sold. What system is this?$q$, $q${"A":"Subsistence or peasant farming","B":"Commercial export farming","C":"Industrial manufacturing","D":"Distributive trade"}$q$::jsonb, $q$A$q$, $q$Subsistence farming is primarily for the farmer's household needs.$q$),
  ($q$Agriculture$q$, $q$A group of farmers jointly buys a tractor and markets its harvest. What system are they using?$q$, $q${"A":"Individual subsistence farming","B":"Co-operative farming","C":"A central bank","D":"An import quota"}$q$::jsonb, $q$B$q$, $q$Co-operative farming pools members' resources and benefits.$q$),
  ($q$Agriculture$q$, $q$A government guarantees a minimum crop price to reduce farmers' losses during a price collapse. What is the intended effect?$q$, $q${"A":"Higher rainfall","B":"No need for storage","C":"More stable farm income","D":"Elimination of all farm costs"}$q$::jsonb, $q$C$q$, $q$A price floor can support farm income when market prices are low.$q$),
  ($q$Agriculture$q$, $q$A country exports cocoa but imports much of its food. What risk does this create?$q$, $q${"A":"Guaranteed food self-sufficiency","B":"No exposure to world prices","C":"Zero transport costs","D":"Dependence on export earnings and food imports"}$q$::jsonb, $q$D$q$, $q$Relying on export crops and imported food exposes the economy to external price and supply changes.$q$),
  ($q$Agriculture$q$, $q$Poor roads cause harvested vegetables to spoil before sale. Which policy would most directly help?$q$, $q${"A":"Improve farm-to-market transport","B":"Reduce soil fertility","C":"Ban local markets","D":"Raise the cost of storage"}$q$::jsonb, $q$A$q$, $q$Better roads cut travel time and post-harvest losses.$q$),
  ($q$Agriculture$q$, $q$A farmer uses irrigation to produce vegetables during the dry season. What constraint is being eased?$q$, $q${"A":"A permanent shortage of labour","B":"Seasonal water shortage","C":"A lack of buyers","D":"The law of diminishing returns"}$q$::jsonb, $q$B$q$, $q$Irrigation supplies water when rainfall is insufficient.$q$),
  ($q$Agriculture$q$, $q$A commodity board purchases farmers' crops for resale. Which function is it performing?$q$, $q${"A":"Commercial banking","B":"Monetary policy","C":"Organized marketing","D":"Population enumeration"}$q$::jsonb, $q$C$q$, $q$The board aggregates and markets agricultural produce.$q$),
  ($q$Agriculture$q$, $q$A rise in farm output supplies food and raw material to local factories. What connection does this illustrate?$q$, $q${"A":"Industry must replace all farming","B":"Food output has no effect on industry","C":"Factories only use imported inputs","D":"Agriculture can support industrialization"}$q$::jsonb, $q$D$q$, $q$Agricultural output can feed workers and supply agro-processing firms.$q$),
  ($q$Industrialization$q$, $q$Several firms making similar products locate near one another and share suppliers. What is this concentration called?$q$, $q${"A":"Localization of industry","B":"Nationalization","C":"Price discrimination","D":"Import substitution alone"}$q$::jsonb, $q$A$q$, $q$Localization is the concentration of related firms in a particular area.$q$),
  ($q$Industrialization$q$, $q$A firm places a cement plant near limestone deposits. What location factor is most important?$q$, $q${"A":"Proximity to a stock exchange","B":"Proximity to bulky raw material","C":"Access to school uniforms","D":"Availability of foreign tourists"}$q$::jsonb, $q$B$q$, $q$Transporting heavy limestone is costly, so nearby raw materials matter.$q$),
  ($q$Industrialization$q$, $q$A small manufacturing firm uses the same road, power line and training centre as nearby firms. What benefit is this?$q$, $q${"A":"A monopoly profit","B":"An internal diseconomy","C":"External economies of scale","D":"A demand shortage"}$q$::jsonb, $q$C$q$, $q$Shared area infrastructure lowers costs for multiple firms.$q$),
  ($q$Industrialization$q$, $q$A government builds an industrial estate with roads and reliable electricity. What is its immediate purpose?$q$, $q${"A":"Eliminate consumer demand","B":"Replace every private firm","C":"Prevent all imports","D":"Lower setup costs for manufacturers"}$q$::jsonb, $q$D$q$, $q$Common infrastructure can make manufacturing investment easier.$q$),
  ($q$Industrialization$q$, $q$A country assembles locally goods it previously imported, aiming to reduce import dependence. Which strategy is it following?$q$, $q${"A":"Import-substitution industrialization","B":"Export of raw materials only","C":"Deindustrialization","D":"Pure barter"}$q$::jsonb, $q$A$q$, $q$Import substitution develops domestic production of formerly imported goods.$q$),
  ($q$Industrialization$q$, $q$A manufacturer cannot expand because power outages repeatedly stop machines. What bottleneck is described?$q$, $q${"A":"Excess demand for exports","B":"Inadequate infrastructure","C":"Too much human capital","D":"Perfect capital mobility"}$q$::jsonb, $q$B$q$, $q$Unreliable electricity is an infrastructure constraint on industrial output.$q$),
  ($q$Industrialization$q$, $q$A firm operates three factories, each making a different product. Which term refers to the whole business organization?$q$, $q${"A":"Plant","B":"Machine","C":"Firm","D":"Workshop floor"}$q$::jsonb, $q$C$q$, $q$A firm is the business organization; each factory is a plant.$q$),
  ($q$Industrialization$q$, $q$Why might new industries matter for economic development?$q$, $q${"A":"They eliminate scarcity","B":"They always reduce every price","C":"They remove the need for agriculture","D":"They can diversify output and create jobs"}$q$::jsonb, $q$D$q$, $q$Industry can broaden production and employment, though outcomes depend on conditions.$q$),
  ($q$National Income$q$, $q$An economy's consumption is ₦500bn, investment ₦120bn, government spending ₦180bn, exports ₦70bn and imports ₦90bn. What is GDP by expenditure?$q$, $q${"A":"₦780bn","B":"₦800bn","C":"₦960bn","D":"₦700bn"}$q$::jsonb, $q$A$q$, $q$GDP = C + I + G + X − M = 500 + 120 + 180 + 70 − 90 = ₦780bn.$q$),
  ($q$National Income$q$, $q$A bakery buys flour for ₦40 and sells bread for ₦100. What value does it add?$q$, $q${"A":"₦40","B":"₦60","C":"₦100","D":"₦140"}$q$::jsonb, $q$B$q$, $q$Value added = sale value − intermediate input cost = 100 − 40 = ₦60.$q$),
  ($q$National Income$q$, $q$GDP is ₦900bn and depreciation is ₦80bn. What is net domestic product?$q$, $q${"A":"₦980bn","B":"₦80bn","C":"₦820bn","D":"₦900bn"}$q$::jsonb, $q$C$q$, $q$Net domestic product = GDP − depreciation = 900 − 80 = ₦820bn.$q$),
  ($q$National Income$q$, $q$Why are intermediate goods excluded when calculating GDP from final output?$q$, $q${"A":"Because they have no price","B":"Because factories do not use them","C":"Because they are always imported","D":"To avoid counting the same value more than once"}$q$::jsonb, $q$D$q$, $q$Their value is already included in the final goods' value.$q$),
  ($q$National Income$q$, $q$A country produces GDP of ₦1,000bn and receives ₦50bn net factor income from abroad. What is GNP?$q$, $q${"A":"₦1,050bn","B":"₦950bn","C":"₦1,000bn","D":"₦50bn"}$q$::jsonb, $q$A$q$, $q$GNP = GDP + net factor income from abroad = 1,000 + 50 = ₦1,050bn.$q$),
  ($q$National Income$q$, $q$National income is ₦600bn for a population of 30 million. What is income per person?$q$, $q${"A":"₦2,000","B":"₦20,000","C":"₦200,000","D":"₦18,000"}$q$::jsonb, $q$B$q$, $q$Per-capita income = ₦600 billion ÷ 30 million = ₦20,000.$q$),
  ($q$National Income$q$, $q$A country's measured GDP grows after unpaid household care is replaced by paid care. What limitation of GDP does this show?$q$, $q${"A":"GDP counts every unpaid activity","B":"GDP directly measures happiness","C":"Unpaid work is often omitted","D":"GDP cannot include services"}$q$::jsonb, $q$C$q$, $q$National accounts generally record market production, not most unpaid household work.$q$),
  ($q$National Income$q$, $q$A rise in GDP comes mainly from price increases rather than more goods. Which measure better tracks real output?$q$, $q${"A":"Nominal GDP alone","B":"Import duty revenue","C":"The money supply alone","D":"Real GDP adjusted for inflation"}$q$::jsonb, $q$D$q$, $q$Real GDP removes the effect of changing prices.$q$),
  ($q$Money and Inflation$q$, $q$A fisher wants rice but the rice seller wants shoes, not fish. What barter problem occurs?$q$, $q${"A":"Lack of double coincidence of wants","B":"Excess bank reserves","C":"A budget surplus","D":"Currency appreciation"}$q$::jsonb, $q$A$q$, $q$Barter requires each side to want what the other offers at the same time.$q$),
  ($q$Money and Inflation$q$, $q$A worker keeps part of her wages in cash for future purchases. Which function of money is this?$q$, $q${"A":"Unit of account only","B":"Store of value","C":"A production factor","D":"A tax rate"}$q$::jsonb, $q$B$q$, $q$Money can transfer purchasing power from the present to a later time.$q$),
  ($q$Money and Inflation$q$, $q$A basket costs ₦100 last year and ₦110 this year. What is the inflation rate measured by this basket?$q$, $q${"A":"5%","B":"11%","C":"10%","D":"110%"}$q$::jsonb, $q$C$q$, $q$Inflation = (new price − old price) ÷ old price × 100 = (110 − 100) ÷ 100 × 100 = 10%.$q$),
  ($q$Money and Inflation$q$, $q$A harvest failure pushes food prices up because less food is available. What type of pressure is this?$q$, $q${"A":"Demand-pull inflation from higher incomes","B":"Deflation","C":"A productivity boom","D":"Cost-push or supply-side inflation"}$q$::jsonb, $q$D$q$, $q$Reduced supply raises production or scarcity costs and pushes prices upward.$q$),
  ($q$Money and Inflation$q$, $q$If prices rise faster than wages, what happens to workers' purchasing power?$q$, $q${"A":"It falls","B":"It always rises","C":"It stays exactly the same","D":"It becomes unrelated to prices"}$q$::jsonb, $q$A$q$, $q$A given wage buys fewer goods when prices outpace pay.$q$),
  ($q$Money and Inflation$q$, $q$A central bank raises interest rates to restrain borrowing and spending. What is the intended effect on inflation?$q$, $q${"A":"Increase demand immediately","B":"Reduce demand pressure","C":"Eliminate scarcity permanently","D":"Fix all supply shortages"}$q$::jsonb, $q$B$q$, $q$Higher borrowing costs can slow spending and ease demand-driven inflation.$q$),
  ($q$Money and Inflation$q$, $q$A price index rises from 125 to 130 over a year. What is the inflation rate?$q$, $q${"A":"5%","B":"3%","C":"4%","D":"30%"}$q$::jsonb, $q$C$q$, $q$Inflation = (130 − 125) ÷ 125 × 100 = 4%.$q$),
  ($q$Money and Inflation$q$, $q$A shop posts prices in naira so customers can compare products. Which money function is illustrated?$q$, $q${"A":"Means of production","B":"Factor mobility","C":"Balance of trade","D":"Unit of account"}$q$::jsonb, $q$D$q$, $q$A unit of account expresses values in a common measure.$q$),
  ($q$Financial Institutions$q$, $q$A bank accepts deposits and makes loans to households and firms. Which institution is described?$q$, $q${"A":"Commercial bank","B":"Central bank","C":"Commodity board","D":"Trade union"}$q$::jsonb, $q$A$q$, $q$Commercial banks provide deposit and lending services to customers.$q$),
  ($q$Financial Institutions$q$, $q$An authority issues currency and acts as banker to the government. Which institution is this?$q$, $q${"A":"Retail shop","B":"Central bank","C":"Insurance broker","D":"Co-operative farm"}$q$::jsonb, $q$B$q$, $q$A central bank is responsible for currency issue and government banking functions.$q$),
  ($q$Financial Institutions$q$, $q$A farmer buys insurance against loss of livestock. What does the insurer mainly provide?$q$, $q${"A":"A guaranteed increase in farm output","B":"A fixed crop price","C":"Risk pooling and compensation for covered losses","D":"Unlimited government credit"}$q$::jsonb, $q$C$q$, $q$Insurance pools premiums to meet eligible claims when insured risks occur.$q$),
  ($q$Financial Institutions$q$, $q$A business raises long-term funds by issuing shares. Which market does it use?$q$, $q${"A":"Money market","B":"Retail market","C":"Labour market","D":"Capital market"}$q$::jsonb, $q$D$q$, $q$Capital markets supply longer-term finance, including shares.$q$),
  ($q$Financial Institutions$q$, $q$A firm borrows for three months to finance inventory. Which market is most relevant to such short-term funds?$q$, $q${"A":"Money market","B":"Capital market only","C":"Commodity board","D":"Foreign direct investment only"}$q$::jsonb, $q$A$q$, $q$Money markets deal mainly in short-term funds.$q$),
  ($q$Financial Institutions$q$, $q$A development bank lends for long-term infrastructure that ordinary banks avoid. What gap does it address?$q$, $q${"A":"Daily cash change","B":"Long-term project finance","C":"Retail price labels","D":"A shortage of currency notes only"}$q$::jsonb, $q$B$q$, $q$Development banks finance projects needing long repayment periods.$q$),
  ($q$Financial Institutions$q$, $q$A commercial bank keeps reserves at the central bank. Why might it do so?$q$, $q${"A":"To become a retailer","B":"To grow crops","C":"To meet regulation and settle payments","D":"To replace every customer account"}$q$::jsonb, $q$C$q$, $q$Bank reserves support settlement and regulatory requirements.$q$),
  ($q$Financial Institutions$q$, $q$A household places savings in a regulated institution rather than keeping cash at home. Which benefit is most direct?$q$, $q${"A":"Guaranteed immunity from inflation","B":"No need for identification","C":"Automatic profits without risk","D":"Safer custody and access to payment services"}$q$::jsonb, $q$D$q$, $q$Financial institutions can safeguard deposits and provide payment services, though risks remain.$q$),
  ($q$Public Finance$q$, $q$A worker pays ₦15 tax on ₦100 income and ₦30 tax on ₦200 income. What is the tax rate in each case?$q$, $q${"A":"15% in both cases","B":"15% then 30%","C":"30% then 15%","D":"5% in both cases"}$q$::jsonb, $q$A$q$, $q$Tax rate = tax ÷ income × 100. Both 15/100 and 30/200 equal 15%, so this is proportional.$q$),
  ($q$Public Finance$q$, $q$A higher share of income is taxed as income rises. What type of taxation is this?$q$, $q${"A":"Proportional","B":"Progressive","C":"Regressive","D":"A lump-sum rebate"}$q$::jsonb, $q$B$q$, $q$A progressive tax takes a larger percentage at higher incomes.$q$),
  ($q$Public Finance$q$, $q$A sales tax is added to the price of goods. What broad category does it belong to?$q$, $q${"A":"Direct income tax","B":"Capital expenditure","C":"Indirect tax","D":"A public debt repayment"}$q$::jsonb, $q$C$q$, $q$An indirect tax is levied on goods or transactions rather than directly on income.$q$),
  ($q$Public Finance$q$, $q$The government builds a new bridge. Is this mainly recurrent or capital expenditure?$q$, $q${"A":"Recurrent expenditure","B":"A transfer payment only","C":"Interest income","D":"Capital expenditure"}$q$::jsonb, $q$D$q$, $q$A new bridge is a long-lived public asset, so building it is capital spending.$q$),
  ($q$Public Finance$q$, $q$A ministry pays monthly salaries to existing staff. What type of spending is this?$q$, $q${"A":"Recurrent expenditure","B":"Capital expenditure","C":"An export subsidy only","D":"A foreign reserve"}$q$::jsonb, $q$A$q$, $q$Regular salaries are ongoing operating costs.$q$),
  ($q$Public Finance$q$, $q$Government revenue is ₦900bn and expenditure is ₦1,050bn. What is the budget balance?$q$, $q${"A":"₦150bn surplus","B":"₦150bn deficit","C":"₦900bn deficit","D":"₦1,950bn surplus"}$q$::jsonb, $q$B$q$, $q$Balance = revenue − expenditure = 900 − 1,050 = −150; the negative balance is a ₦150bn deficit.$q$),
  ($q$Public Finance$q$, $q$A tax is formally paid by a firm, but the firm raises prices and buyers bear much of it. What concept describes who ultimately bears the tax?$q$, $q${"A":"Tax base only","B":"Tax exemption","C":"Tax incidence","D":"Public debt"}$q$::jsonb, $q$C$q$, $q$Tax incidence concerns the final distribution of a tax burden.$q$),
  ($q$Public Finance$q$, $q$A government borrows to pay for investment projects. What does the accumulated borrowing contribute to?$q$, $q${"A":"Current tax revenue","B":"Private savings only","C":"The money supply alone","D":"Public debt"}$q$::jsonb, $q$D$q$, $q$Borrowing adds to outstanding public debt until repaid.$q$),
  ($q$Economic Development and Planning$q$, $q$A country's output rises, but most households remain without clean water or schooling. Why is output growth alone not proof of development?$q$, $q${"A":"Development also concerns living standards and opportunities","B":"Growth always reduces output","C":"Income cannot be measured","D":"Population must have fallen"}$q$::jsonb, $q$A$q$, $q$Development is broader than output growth and includes welfare and access to services.$q$),
  ($q$Economic Development and Planning$q$, $q$A government sets education and transport targets for the next five years. What is this process?$q$, $q${"A":"Price discrimination","B":"Development planning","C":"Barter","D":"Market clearing"}$q$::jsonb, $q$B$q$, $q$Development planning sets coordinated goals and policies over a period.$q$),
  ($q$Economic Development and Planning$q$, $q$A plan is revised each year as conditions change while keeping a multi-year horizon. What type of plan is this?$q$, $q${"A":"Fixed one-day plan","B":"A census","C":"Rolling plan","D":"A trade embargo"}$q$::jsonb, $q$C$q$, $q$A rolling plan updates and extends the planning period regularly.$q$),
  ($q$Economic Development and Planning$q$, $q$A country has high unemployment despite many working-age people. What development resource is underused?$q$, $q${"A":"Only mineral deposits","B":"Only imported machines","C":"Foreign currency notes","D":"Labour"}$q$::jsonb, $q$D$q$, $q$Unemployment means available labour is not fully employed.$q$),
  ($q$Economic Development and Planning$q$, $q$Why can poor data weaken an economic development plan?$q$, $q${"A":"Targets may be based on inaccurate needs and resources","B":"Data always raises inflation","C":"Plans never use population information","D":"All investments become free"}$q$::jsonb, $q$A$q$, $q$Planning requires reliable estimates of population, output and resources.$q$),
  ($q$Economic Development and Planning$q$, $q$A new factory increases GDP but pollutes drinking water. What trade-off should planners assess?$q$, $q${"A":"Only the factory's sales revenue","B":"Economic gains against environmental and health costs","C":"Only the number of machines","D":"Only the import price of fuel"}$q$::jsonb, $q$B$q$, $q$Development decisions should account for benefits and social or environmental costs.$q$),
  ($q$Economic Development and Planning$q$, $q$A country invests in schools to improve workers' skills over time. Which development input is being strengthened?$q$, $q${"A":"Only mineral capital","B":"Import tariffs","C":"Human capital","D":"Nominal exchange rates"}$q$::jsonb, $q$C$q$, $q$Education builds human capital and can improve productivity.$q$),
  ($q$Economic Development and Planning$q$, $q$An economy depends heavily on one export crop. Why might diversification be a development goal?$q$, $q${"A":"It makes all prices constant","B":"It prevents all imports","C":"It eliminates scarcity","D":"It reduces exposure to one commodity's price shocks"}$q$::jsonb, $q$D$q$, $q$Diversification spreads risk across activities and sources of income.$q$),
  ($q$International Trade and Balance of Payments$q$, $q$Country A can produce a shirt with fewer resources than Country B. Which advantage does A have in shirts?$q$, $q${"A":"Absolute advantage","B":"A guaranteed trade surplus","C":"A balance-of-payments deficit","D":"A tariff advantage"}$q$::jsonb, $q$A$q$, $q$Absolute advantage means producing a good with fewer inputs.$q$),
  ($q$International Trade and Balance of Payments$q$, $q$Two countries can both make food and cloth, but one gives up less cloth to make food. Why may it specialize in food?$q$, $q${"A":"It has no opportunity cost","B":"It has a comparative advantage in food","C":"It must import all cloth","D":"Its population is larger"}$q$::jsonb, $q$B$q$, $q$Comparative advantage depends on the lower opportunity cost.$q$),
  ($q$International Trade and Balance of Payments$q$, $q$A country exports goods worth ₦500bn and imports goods worth ₦420bn. What is its merchandise trade balance?$q$, $q${"A":"₦80bn deficit","B":"₦920bn surplus","C":"₦80bn surplus","D":"₦420bn deficit"}$q$::jsonb, $q$C$q$, $q$Merchandise trade balance = exports − imports = 500 − 420 = ₦80bn surplus.$q$),
  ($q$International Trade and Balance of Payments$q$, $q$An export price index is 120 and an import price index is 150. What are the commodity terms of trade?$q$, $q${"A":"125","B":"30","C":"270","D":"80"}$q$::jsonb, $q$D$q$, $q$Terms of trade = export price index ÷ import price index × 100 = 120 ÷ 150 × 100 = 80.$q$),
  ($q$International Trade and Balance of Payments$q$, $q$A tariff is placed on imported shoes. What is the direct policy action?$q$, $q${"A":"A tax on imports","B":"A quota on exports","C":"A subsidy to foreign firms","D":"An exchange of goods without money"}$q$::jsonb, $q$A$q$, $q$A tariff taxes imported goods.$q$),
  ($q$International Trade and Balance of Payments$q$, $q$A country receives foreign-currency payment for exported cocoa. Where is this receipt recorded in the balance of payments?$q$, $q${"A":"Only the capital account","B":"The current account","C":"The domestic tax account","D":"The central bank's payroll"}$q$::jsonb, $q$B$q$, $q$Exports of goods are recorded in the current account.$q$),
  ($q$International Trade and Balance of Payments$q$, $q$A persistent current-account deficit may be financed by what?$q$, $q${"A":"Printing foreign banknotes domestically","B":"Eliminating every import immediately","C":"Borrowing or drawing down foreign reserves","D":"Ignoring foreign payments"}$q$::jsonb, $q$C$q$, $q$A deficit requires financing, such as external borrowing or reserve use.$q$),
  ($q$International Trade and Balance of Payments$q$, $q$A country's export value is ₦240bn and import value is ₦300bn. By how much do imports exceed exports?$q$, $q${"A":"₦540bn","B":"₦240bn","C":"₦300bn","D":"₦60bn"}$q$::jsonb, $q$D$q$, $q$Imports exceed exports by 300 − 240 = ₦60bn.$q$),
  ($q$Economic Integration$q$, $q$Neighbouring states remove tariffs on goods traded among themselves but keep separate tariffs on outsiders. What is the arrangement?$q$, $q${"A":"Free-trade area","B":"Customs union","C":"Monetary union","D":"A single firm"}$q$::jsonb, $q$A$q$, $q$A free-trade area removes internal tariffs while members retain separate external tariffs.$q$),
  ($q$Economic Integration$q$, $q$Members remove internal tariffs and adopt one common external tariff. What is this?$q$, $q${"A":"Free-trade area only","B":"Customs union","C":"Barter agreement","D":"A fixed exchange rate alone"}$q$::jsonb, $q$B$q$, $q$A customs union combines free internal trade with a common external tariff.$q$),
  ($q$Economic Integration$q$, $q$Countries permit goods, labour and capital to move freely among members. What level of integration is this?$q$, $q${"A":"A tariff quota only","B":"A bilateral loan","C":"Common market","D":"A single tax office"}$q$::jsonb, $q$C$q$, $q$A common market adds free movement of production factors to goods trade.$q$),
  ($q$Economic Integration$q$, $q$A small producer gains access to buyers across several member countries. What is a potential benefit of integration?$q$, $q${"A":"Guaranteed monopoly profit","B":"No transport costs","C":"No need for product quality","D":"A larger market"}$q$::jsonb, $q$D$q$, $q$Regional integration can expand the market available to firms.$q$),
  ($q$Economic Integration$q$, $q$A less industrialized member fears its firms will lose to stronger neighbours. What is this a concern about?$q$, $q${"A":"Unequal distribution of integration benefits","B":"The absence of any competition","C":"A fall in market size for all members","D":"The end of specialization"}$q$::jsonb, $q$A$q$, $q$Benefits may be uneven when firms have different competitive capacities.$q$),
  ($q$Economic Integration$q$, $q$ECOWAS tries to make trade easier within West Africa. Which objective does this most directly serve?$q$, $q${"A":"An end to all national governments","B":"Regional economic integration","C":"A single global currency","D":"The abolition of agriculture"}$q$::jsonb, $q$B$q$, $q$Reducing barriers among members advances regional integration.$q$),
  ($q$Economic Integration$q$, $q$Different product standards slow trade among member states. What measure could help?$q$, $q${"A":"Raise internal tariffs","B":"Ban all regional transport","C":"Harmonize product standards","D":"Remove every quality check"}$q$::jsonb, $q$C$q$, $q$Compatible standards reduce technical obstacles while preserving quality checks.$q$),
  ($q$Economic Integration$q$, $q$Why may poor cross-border roads limit the gains from a free-trade agreement?$q$, $q${"A":"Tariff removal creates roads automatically","B":"Trade no longer needs logistics","C":"All goods become weightless","D":"Transport costs can still make trade expensive"}$q$::jsonb, $q$D$q$, $q$Low tariffs alone do not remove physical transport costs.$q$),
  ($q$International Economic Organizations$q$, $q$A country seeks short-term support during a balance-of-payments crisis. Which institution is most closely associated with this role?$q$, $q${"A":"International Monetary Fund","B":"OPEC","C":"A local co-operative","D":"A national stock exchange"}$q$::jsonb, $q$A$q$, $q$The IMF is associated with balance-of-payments assistance and macroeconomic support.$q$),
  ($q$International Economic Organizations$q$, $q$A country seeks long-term financing for a major development project. Which institution is most relevant among these?$q$, $q${"A":"A local wholesaler","B":"World Bank/IBRD","C":"A trade union","D":"A retail bank's cash desk"}$q$::jsonb, $q$B$q$, $q$The IBRD, part of the World Bank, supports development financing.$q$),
  ($q$International Economic Organizations$q$, $q$Oil-exporting countries coordinate petroleum production policy through which organization?$q$, $q${"A":"AfDB","B":"ECOWAS only","C":"OPEC","D":"A commodity retailer"}$q$::jsonb, $q$C$q$, $q$OPEC groups oil-exporting countries for petroleum policy coordination.$q$),
  ($q$International Economic Organizations$q$, $q$An African country seeks a regional development loan. Which institution is specifically African in focus?$q$, $q${"A":"International Olympic Committee","B":"A private insurance shop","C":"A national retail union","D":"African Development Bank"}$q$::jsonb, $q$D$q$, $q$The AfDB finances development in African member countries.$q$),
  ($q$International Economic Organizations$q$, $q$A West African country wants analysis of African economic development trends from a UN regional body. Which body fits?$q$, $q${"A":"Economic Commission for Africa","B":"OPEC","C":"A village co-operative","D":"A local customs post"}$q$::jsonb, $q$A$q$, $q$The UN Economic Commission for Africa focuses on African development policy.$q$),
  ($q$International Economic Organizations$q$, $q$A government wants a UN forum focused on trade and development issues affecting lower-income countries. Which body is most relevant?$q$, $q${"A":"OPEC","B":"UNCTAD","C":"A domestic sports federation","D":"A commercial bank branch"}$q$::jsonb, $q$B$q$, $q$UNCTAD addresses trade and development issues in the UN system.$q$),
  ($q$International Economic Organizations$q$, $q$Why might several countries join a development bank rather than finance every project alone?$q$, $q${"A":"They can abolish loan repayment","B":"They can remove all exchange rates","C":"They can pool resources and risk","D":"They can guarantee every project succeeds"}$q$::jsonb, $q$C$q$, $q$Multilateral institutions pool finance and share project risk, though loans still need repayment.$q$),
  ($q$International Economic Organizations$q$, $q$A country compares policy advice from an international lender with local employment needs. What is the sound approach?$q$, $q${"A":"Accept every recommendation without analysis","B":"Reject all data from abroad","C":"Ignore the cost of borrowing","D":"Assess advice against national conditions and trade-offs"}$q$::jsonb, $q$D$q$, $q$Policy advice should be evaluated against a country's circumstances and objectives.$q$),
  ($q$Major Natural Resources$q$, $q$A country exports unprocessed timber but imports expensive furniture. What opportunity might domestic processing create?$q$, $q${"A":"More local value added","B":"A guaranteed end to deforestation","C":"No need for skilled labour","D":"A fall in all transport costs"}$q$::jsonb, $q$A$q$, $q$Processing timber locally can retain more value in the domestic economy.$q$),
  ($q$Major Natural Resources$q$, $q$A government saves part of oil revenue during high-price years. What risk is it trying to manage?$q$, $q${"A":"A fixed export price forever","B":"Volatile commodity prices","C":"Too many public schools","D":"The impossibility of imports"}$q$::jsonb, $q$B$q$, $q$Saving during booms can cushion budgets when commodity prices fall.$q$),
  ($q$Major Natural Resources$q$, $q$Mining creates jobs but damages nearby farmland. What policy response best addresses both sides?$q$, $q${"A":"Ignore the damage","B":"Close every mine without assessing alternatives","C":"Require environmental safeguards while retaining useful production","D":"Pay no attention to workers"}$q$::jsonb, $q$C$q$, $q$Regulation can reduce environmental harm while allowing economic benefits.$q$),
  ($q$Major Natural Resources$q$, $q$A country relies on one mineral for most export earnings. What makes this risky?$q$, $q${"A":"Minerals never face price changes","B":"Export earnings cannot be saved","C":"Domestic industry always grows automatically","D":"A world-price fall can sharply reduce income"}$q$::jsonb, $q$D$q$, $q$Concentration makes export income vulnerable to one commodity's price.$q$),
  ($q$Major Natural Resources$q$, $q$A company extracts gold but hires few local workers and sends most profits abroad. What concern does this raise?$q$, $q${"A":"Limited domestic linkages and benefits","B":"Excessive local value added","C":"A guaranteed budget surplus","D":"Complete industrial diversification"}$q$::jsonb, $q$A$q$, $q$Resource extraction may add little locally if employment and retained income are limited.$q$),
  ($q$Major Natural Resources$q$, $q$Which investment can help a petroleum-producing country move beyond crude exports?$q$, $q${"A":"Only storing crude indefinitely","B":"Domestic refining and related skills","C":"Eliminating transport networks","D":"Reducing technical training"}$q$::jsonb, $q$B$q$, $q$Refining and skills can add value and create industrial linkages.$q$),
  ($q$Major Natural Resources$q$, $q$A community receives mining royalties but has polluted water. Which measure would best improve welfare?$q$, $q${"A":"Measure royalties only","B":"Increase extraction without safeguards","C":"Use revenue for clean water and enforce pollution controls","D":"Ignore health costs"}$q$::jsonb, $q$C$q$, $q$Resource income should be weighed against environmental costs and used to improve local welfare.$q$),
  ($q$Major Natural Resources$q$, $q$Why is it useful to invest some non-renewable resource revenue in education?$q$, $q${"A":"It makes the mineral renewable","B":"It eliminates all future taxes","C":"It guarantees a fixed global price","D":"It creates lasting human capital after the resource is depleted"}$q$::jsonb, $q$D$q$, $q$Education turns temporary resource income into longer-lived productive capacity.$q$)
)
INSERT INTO public.questions (
  subject_id, exam_type, source, year, topic,
  prompt, options, correct_answer, explanation
)
SELECT
  subject.id, subject.exam_type, $q$original$q$, NULL,
  candidate.topic, candidate.prompt, candidate.options,
  candidate.correct_answer, candidate.explanation
FROM candidates AS candidate
CROSS JOIN public.subjects AS subject
WHERE subject.id = 'e25adcfa-580c-46bc-87be-048ef2231b02'::uuid
  AND lower(subject.exam_type::text) = 'waec'
  AND NOT EXISTS (
    SELECT 1 FROM public.questions AS existing
    WHERE existing.subject_id = subject.id
      AND existing.source = $q$original$q$
      AND existing.prompt = candidate.prompt
  );
